    expect(response.json().slots).toHaveLength(1);
    expect(response.json().slots[0].startsAt).toBe(inHours(24));
    expect(response.json().slots[0].endsAt).toBe(inHours(28));
  });

  it('omits a free gap shorter than the minimum bookable duration', async () => {
    await book(24, 24.5, 'First');
    await book(24.75, 25.25, 'Second');
