    expect(response.json().slots).toEqual([{ startsAt: inHours(25.25), endsAt: inHours(26) }]);
  });

  it('filters gaps by a requested minimum duration', async () => {
    await book(24, 24.5, 'First');
    await book(24.75, 25.25, 'Second');
    const response = await availability(24, 26, '&duration=60');
    expect(response.json().slots).toEqual([]);
  });

  it('answers 404 for availability of a room that does not exist', async () => {
    const response = await app.inject({
      method: 'GET',
      url: `/bookings/availability?roomId=missing&from=${inHours(24)}&to=${inHours(25)}`,
    });
    expect(response.statusCode).toBe(404);
  });

  it('rejects an availability window where `to` is not after `from`', async () => {
    const response = await availability(25, 24);
    expect(response.statusCode).toBe(400);
    expect(response.json().error.code).toBe('VALIDATION_ERROR');
  });
});

