    });
  }

  it('reports the whole window as free when there are no bookings', async () => {
    const response = await availability(24, 28);
    expect(response.statusCode).toBe(200);
    expect(response.json().slots).toHaveLength(1);
    expect(new Date(response.json().slots[0].startsAt)).toEqual(new Date(inHours(24)));
    expect(new Date(response.json().slots[0].endsAt)).toEqual(new Date(inHours(28)));
  });

  it('excludes booked ranges from availability', async () => {
    await book(25, 26);
    const response = await availability(24, 28);
    expect(response.json().slots).toEqual([
      { startsAt: inHours(24), endsAt: inHours(25) },
      { startsAt: inHours(26), endsAt: inHours(28) },
    ]);
  });

  it('ignores a cancelled booking when computing availability', async () => {
    const created = await book(25, 26);
    await app.inject({ method: 'POST', url: `/bookings/${created.json().id}/cancel` });
    const response = await availability(24, 28);
    expect(response.json().slots).toHaveLength(1);
    expect(response.json().slots[0].startsAt).toBe(inHours(24));
    expect(response.json().slots[0].endsAt).toBe(inHours(28));
  });

  it('omits a free gap shorter than the minimum bookable duration', async () => {
    await book(24, 24.5, 'First');
    await book(24.75, 25.25, 'Second');
    const response = await availability(24, 26);
    expect(response.json().slots).toEqual([{ startsAt: inHours(25.25), endsAt: inHours(26) }]);
  });

  it('filters gaps by a requested minimum duration', async () => {
    await book(24, 24.5, 'First');
    await book(24.75, 25.25, 'Second');
    const response = await availability(24, 26, '&duration=60');
    expect(response.json().slots).toEqual([]);
  });

  it('answers 404 for availability of a room that does not exist', async () => {
    const response = await app.inject({
      method: 'GET',
      url: `/bookings/availability?roomId=missing&from=${inHours(24)}&to=${inHours(25)}`,
    });
    expect(response.statusCode).toBe(404);
  });

  it('rejects an availability window where `to` is not after `from`', async () => {
    const response = await availability(25, 24);
    expect(response.statusCode).toBe(400);
    expect(response.json().error.code).toBe('VALIDATION_ERROR');
  });
});

